cat > /tmp/inspect.cs << 'EOF'
using System.Reflection;

var commonDll = Path.Combine(
    Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),
    ".nuget/packages/xunit.v3.common/3.2.2/lib/netstandard2.0/xunit.v3.common.dll");
var coreDll = Path.Combine(
    Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),
    ".nuget/packages/xunit.v3.core/3.2.2/lib/net8.0/xunit.v3.core.dll");

foreach (var dll in new[] { commonDll, coreDll }) {
    if (!File.Exists(dll)) { Console.WriteLine($"Not found: {dll}"); continue; }
    var asm = Assembly.LoadFrom(dll);
    var type = asm.GetTypes().FirstOrDefault(t => t.Name == "CollectionBehaviorAttribute");
    if (type == null) continue;
    Console.WriteLine($"Found in: {dll}");
    Console.WriteLine("Constructors:");
    foreach (var c in type.GetConstructors())
        Console.WriteLine($"  ({string.Join(", ", c.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"))})");
    Console.WriteLine("Properties:");
    foreach (var p in type.GetProperties(BindingFlags.Public | BindingFlags.Instance))
        Console.WriteLine($"  {p.PropertyType.Name} {p.Name} {(p.CanWrite?"[set]":"")}");

    // Also check TestCaseOrdererAttribute
    var orderer = asm.GetTypes().FirstOrDefault(t => t.Name == "TestCaseOrdererAttribute");
    if (orderer != null) {
        Console.WriteLine($"\nTestCaseOrdererAttribute:");
        Console.WriteLine("Constructors:");
        foreach (var c in orderer.GetConstructors())
            Console.WriteLine($"  ({string.Join(", ", c.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"))})");
    }
}
EOF
